sess = json.load(open(SESS, encoding="utf-8")) if os.path.exists(SESS) else []
lines = [l for l in open(JSNL, encoding="utf-8")] if os.path.exists(JSNL) else []
existing = {r["goal"] for r in sess}
base = datetime(2026, 8, 16, 9, 0, 0); added = 0
for i, (intent, sub, goal, params, missing, clar, risk, confirm, plan, steps, verif,
        rollback, resolved, summary, rec, fb) in enumerate(R):
    if goal in existing: continue
    created = base + timedelta(minutes=14*i)
    st = [{"command": c, "blocked": b, "exitCode": e, "stdout": o, "stderr": er, "reason": rs}
          for c, b, e, o, er, rs in steps]
    sess.append({"id": str(uuid.uuid4()),
        "createdAt": created.strftime("%Y-%m-%dT%H:%M:%S.000Z"),
        "type": "automation", "goal": goal, "intent": intent,
        "domain": "automation", "subdomain": sub, "parameters": params,
        "missingParameters": missing, "clarification": clar, "riskLevel": risk,
        "requiresConfirmation": confirm, "plannedAction": plan, "steps": st,
        "verification": [{"command": c, "expected": e} for c, e in verif],
        "rollback": rollback, "resolved": resolved, "summary": summary, "recommendation": rec,
        "feedback": {"worked": fb[0], "note": fb[1],
                     "at": (created+timedelta(minutes=7)).strftime("%Y-%m-%dT%H:%M:%S.000Z")}})
    parts = [f"INTENT: {intent}", "PARAMETERS: " + json.dumps(params, ensure_ascii=False)]
    if missing:
        parts.append("MISSING: " + ", ".join(missing))
        parts.append("I need to ask before proceeding:\n" + clar)
    parts.append(f"RISK: {risk}   CONFIRMATION REQUIRED: {'yes' if confirm else 'no'}")
    parts.append("PLANNED ACTION:\n" + plan)
    ex = [s for s in steps if not s[1]]; gate = [s for s in steps if s[1]]
    if ex: parts.append("STEPS:\n" + "\n".join(f"- {s[0]}" + (f"  [FAILED: {s[4][:70]}]" if s[2] else "") for s in ex))
    if gate: parts.append("STOPPED FOR CONFIRMATION: " + (gate[0][5] or "user approval required"))
    if verif: parts.append("VERIFICATION:\n" + "\n".join(f"- {c}  -> expect: {e}" for c, e in verif))
    if rollback: parts.append("ROLLBACK: " + rollback)
    parts.append("RESULT: " + summary); parts.append("RECOMMENDATION: " + rec)
    if not resolved: parts.append("NOTE: not executed - awaiting your decision.")
    lines.append(json.dumps({"messages":[{"role":"system","content":SYSTEM},
        {"role":"user","content":goal},
        {"role":"assistant","content":"\n\n".join(parts)}]}, ensure_ascii=False)+"\n")
    existing.add(goal); added += 1

json.dump(sess, open(SESS,"w",encoding="utf-8"), indent=2, ensure_ascii=False)
open(JSNL,"w",encoding="utf-8").writelines(lines)
print(f"added: {added} | automation total: {len(sess)} | intents: {len(set(r['intent'] for r in sess))}")
print(f"gate: {sum(1 for r in sess if any(s['blocked'] for s in r['steps']))} | clarify: {sum(1 for r in sess if r['missingParameters'])} | not executed: {sum(1 for r in sess if not r['resolved'])}")
